--
-- Name: format_phone_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.format_phone_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- Remove everything except digits
    NEW.phone := regexp_replace(NEW.phone, '[^0-9]', '', 'g');

    -- Auto format to XXX-XXXXXXX
    IF length(NEW.phone) = 10 THEN
        NEW.phone :=
            substring(NEW.phone FROM 1 FOR 3)
            || '-' ||
            substring(NEW.phone FROM 4 FOR 7);
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: generate_branch_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_branch_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.branch_id IS NULL THEN
        NEW.branch_id := nextval(pg_get_serial_sequence('branch', 'branch_id'));
    END IF;

    IF NEW.branch_code IS NULL OR NEW.branch_code = '' THEN
        NEW.branch_code := 'B' || LPAD(NEW.branch_id::TEXT, 4, '0');
    END IF;

    RETURN NEW;
END;
$$;


