--
-- Name: receive_purchase(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_purchase(p_purchase_id integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status VARCHAR(20);
    v_branch_id INT;
    item RECORD;
BEGIN
    SELECT status, branch_id
    INTO v_status, v_branch_id
    FROM public.purchase
    WHERE purchase_id = p_purchase_id;

    IF NOT FOUND THEN
        RETURN 'Purchase order not found.';
    END IF;

    IF v_status = 'RECEIVED' THEN
        RETURN 'Purchase order already received.';
    END IF;

    IF v_status = 'CANCELLED' THEN
        RETURN 'Cannot receive a cancelled purchase order.';
    END IF;

    FOR item IN
        SELECT product_id, quantity
        FROM public.purchase_detail
        WHERE purchase_id = p_purchase_id
    LOOP
            product_id,
            branch_id,
            quantity_in_stock,
            last_updated
        )
        VALUES (
            item.product_id,
            v_branch_id,
            item.quantity,
            CURRENT_TIMESTAMP
        )
        ON CONFLICT (product_id, branch_id)
        DO UPDATE SET
            quantity_in_stock = public.inventory.quantity_in_stock + EXCLUDED.quantity_in_stock,
            last_updated = CURRENT_TIMESTAMP;
    END LOOP;

    UPDATE public.purchase
    SET status = 'RECEIVED',
        updated_at = CURRENT_TIMESTAMP
    WHERE purchase_id = p_purchase_id;

    RETURN 'Purchase received and inventory updated successfully.';
END;
$$;


--
-- Name: update_purchase_total_amount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_purchase_total_amount() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE public.purchase
    SET total_amount = (
        SELECT COALESCE(SUM(subtotal), 0)
        FROM public.purchase_detail
        WHERE purchase_id = COALESCE(NEW.purchase_id, OLD.purchase_id)
    ),
    updated_at = CURRENT_TIMESTAMP
    WHERE purchase_id = COALESCE(NEW.purchase_id, OLD.purchase_id);

    RETURN NULL;
END;
$$;


